import { Settings } from "../context/BotStateContext"

/**
 * Recursively makes all properties optional through nested objects, while preserving array types.
 *
 * Why this exists: character presets only need to override fields that differ from defaults.
 * `Partial<Settings>` makes top-level keys optional but inner blocks must satisfy the FULL type,
 * which means every time a new field is added to Settings, all 6 presets must be updated or TS
 * errors out (e.g., 255 errors in this file when alarmClockPolicy was added). DeepPartial fixes
 * this — presets only specify what they override; missing fields fall through to defaults at
 * runtime via the existing shallow-merge in Home/index.tsx (`{ ...merged[category], ...preset[category] }`).
 *
 * Arrays are kept as their original type (not `(T | undefined)[]`) since presets always provide
 * complete arrays when they override an array field.
 */
type DeepPartial<T> = {
    [P in keyof T]?: T[P] extends (infer U)[] ? U[] : T[P] extends object ? DeepPartial<T[P]> : T[P]
}

export interface CharacterPreset {
    name: string
    /** Canonical in-game trainee identity for Trainee Select, used when the display `name` carries a
     * variant suffix that is NOT a real in-game outfit (e.g. "Super Creek (Blue Farm)" selects the
     * trainee "Super Creek"). Omit for plain presets and real-outfit presets, which select by `name`. */
    traineeName?: string
    scenario: string
    settings: DeepPartial<Settings>
}

/**
 * Optional advisory metadata: which scenarios are a good/bad fit for a given trainee.
 *
 * `recommended` — scenarios where this trainee's signature events, stat curve,
 * or aptitude grades are an above-average fit. Shown on Home as a green "good pick"
 * hint when the user has the matching scenario selected.
 *
 * `avoid` — scenarios where the trainee is a known-mismatch (wrong distance, the
 * scenario's race schedule fights their stat target, secret-event prerequisites missing).
 * Shown on Home as a yellow warning when the user picks an avoid-scenario preset combo.
 *
 * Both fields are optional. Trainees with no entry in this map render no banner.
 *
 * Keyed by trainee `name` (matching `CharacterPreset.name`). Living in a separate map
 * (instead of per-preset fields) keeps each trainee's advice in one place rather than
 * duplicating across the 3 scenario entries each trainee has.
 */
export interface ScenarioAdvisory {
    scenario: string
    reason: string
}

