                enableRacingPlan: false,
                enableMandatoryRacingPlan: false,
                racingPlan: "",
                minFansThreshold: 3500,
                // "Any", not "Turf": the terrain preference is a hard filter and her career
                // is dirt through turn 48 (debut, Japan Dirt Derby, Tokyo Daishoten) before
