                preferredTerrain: "Any",
                preferredGrades: ["G1", "G2", "G3", "OP", "Pre-OP"],
                // Medium goals dominate (Takarazuka, Mainichi Okan, Tenno Autumn); Long
                // carries Tenno Spring + Arima. Mile B stays for the turn 67 Mainichi Okan.
                preferredDistances: ["Medium", "Long", "Mile", "Short"],
                lookAheadDays: 10,
                smartRacingCheckInterval: 2,
                juniorYearRaceStrategy: "Default",
                originalRaceStrategy: "Default",
                minimumQualityThreshold: 50,
                timeDecayFactor: 0.7,
                improvementThreshold: 50,
